package com.library.controller; import com.library.common.annotation.RequireRole; import com.library.common.constant.RoleConstant; import com.library.common.model.ApiResult; import com.library.service.AIService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ai") public class AIController {private final AIService service;public AIController(AIService service){this.service=service;} @PostMapping("/recommend") @RequireRole(RoleConstant.READER) public ApiResult<String> recommend(@RequestBody String prompt){return ApiResult.success(service.readerRecommend(prompt));} @PostMapping("/advice") @RequireRole(RoleConstant.ADMIN) public ApiResult<String> advice(@RequestBody String prompt){return ApiResult.success(service.adminAdvice(prompt));} }
